  const totals = invoiceTotals(result.value);
  const subtotal = 100 * 50 + 10 * 980 + 1 * 120000;
  const vat = roundCents(5000 * 21 / 100) + roundCents(9800 * 21 / 100) + roundCents(120000 * 21 / 100);
  assert.deepEqual(totals, {
    subtotal,
    discount: 0,
    vat,
    total: subtotal + vat,
  });
});

